/** static bool32 MoveTimeUpDown(s16 *val, int minVal, int maxVal, u16 keys) */
export function MoveTimeUpDown(val: any, minVal: any, maxVal: any, keys: any): any {
  if (keys & DPAD_DOWN)
      {
          val -= 1;
          if (val < minVal)
              val = maxVal;
      }
      else if (keys & DPAD_UP)
      {
          val += 1;
          if (val > maxVal)
              val = minVal;
      }
      else if (keys & DPAD_LEFT)
      {
          val -= 10;
          if (val < minVal)
              val = maxVal;
      }
      else if (keys & DPAD_RIGHT)
      {
          val += 10;
          if (val > maxVal)
              val = minVal;
      }
      else
      {
          return FALSE;
      }

      return TRUE;
}

